const float head_b[] = {0.00105042f};

class QRNNModel {
public:
  static const int INPUT_SIZE = 1;
  static const int K          = 1;

  /**
   * Run a forward pass and write K quantile estimates to *output*.
   *
   * @param x       Input array of length INPUT_SIZE.
   * @param output  Output array of length K (caller-allocated).
   */
  void predict(const float* x, float* output) {
    float buf_a[64];
    float buf_b[64];
    const float* in_ptr  = x;
    float*       out_ptr = buf_a;

    // --- Hidden layer 0  (1 → 64, tanh) ---
    for (int k = 0; k < 64; k++) {
      float acc = h0_b[k];
      for (int j = 0; j < 1; j++)
        acc += h0_w[k][j] * in_ptr[j];
      acc = tanhf(acc);
      out_ptr[k] = acc;
    }

    // Swap buffers
    in_ptr  = out_ptr;
    out_ptr = (out_ptr == buf_a) ? buf_b : buf_a;

    // --- Hidden layer 1  (64 → 64, tanh) ---
    for (int k = 0; k < 64; k++) {
      float acc = h1_b[k];
      for (int j = 0; j < 64; j++)
        acc += h1_w[k][j] * in_ptr[j];
      acc = tanhf(acc);
      out_ptr[k] = acc;
    }

    // Swap buffers
    in_ptr  = out_ptr;
    out_ptr = (out_ptr == buf_a) ? buf_b : buf_a;

    // --- Quantile head (64 → 1) ---
    float raw[1];
    for (int k = 0; k < 1; k++) {
      float acc = head_b[k];
      for (int j = 0; j < 64; j++)
        acc += head_w[k][j] * in_ptr[j];
      raw[k] = acc;
    }

    // Single quantile — pass through directly
    output[0] = raw[0];
  }
};